    def _go_lexes(t):
        i, n, depth = 0, len(t), 0
        while i < n:
            c = t[i]
            if t.startswith("//", i):
                j = t.find("\n", i)
                i = n if j < 0 else j
            elif t.startswith("/*", i):
                j = t.find("*/", i + 2)
                if j < 0:
                    return False
                i = j + 2
            elif c in "\"'":
                i += 1
                while i < n and t[i] != c:
                    if t[i] == "\n":
                        return False
                    i += 2 if t[i] == "\\" else 1
                if i >= n:
                    return False
                i += 1
            elif c == "`":
                j = t.find("`", i + 1)
                if j < 0:
                    return False
                i = j + 1
            else:
                depth += (c in "{([") - (c in "})]")
                if depth < 0:
                    return False
                i += 1
        return depth == 0

